typedef int (*callback_t)(int, void *);
int process_data(int data, void *context, callback_t callback) {
    // Invoke the callback with data and context
    return callback(data, context);
}
int my_callback(int value, void *ctx) {
    // Custom processing logic
    return value * 2;
}
int result = process_data(10, NULL, my_callback);
